// === CONFIGURATION : modifiez cette liste avec vos propres cibles ===
const TARGETS = [
  { name: 'Site web (demo)', url: 'https://example.com' },
  { name: 'Serveur test FICTIF (panne simulee)', url: 'http://127.0.0.1:9' }
];
const FAILS_BEFORE_ALERT = 2; // alerte apres 2 echecs consecutifs (evite les fausses alertes)
// =====================================================================
const fmt = (d) => new Date(d).toLocaleString('fr-FR', { timeZone: 'Indian/Antananarivo' });
const state = $getWorkflowStaticData('global');
state.targets = state.targets || {};
const now = new Date().toISOString();
const events = [];
for (const t of TARGETS) {
  const s = state.targets[t.name] || { up: true, fails: 0, since: now, checks: 0, okChecks: 0 };
  let ok = false;
  try {
    await this.helpers.httpRequest({ method: 'GET', url: t.url, timeout: 8000 });
    ok = true;
  } catch (e) { ok = false; }
  s.checks++;
  if (ok) {
    s.okChecks++;
    s.fails = 0;
    if (!s.up) {
      events.push({ json: { message: '✅ RETABLI : ' + t.name + '\nPanne depuis : ' + fmt(s.since) + '\nRetour : ' + fmt(now) } });
      s.up = true; s.since = now;
    }
  } else {
    s.fails++;
    if (s.up && s.fails >= FAILS_BEFORE_ALERT) {
      s.up = false; s.since = now;
      events.push({ json: { message: '🚨 PANNE : ' + t.name + '\nDetectee : ' + fmt(now) + '\nCible : ' + t.url } });
    }
  }
  state.targets[t.name] = s;
}
return events;

const state = $getWorkflowStaticData('global');
const t = state.targets || {};
const names = Object.keys(t);
if (!names.length) return [{ json: { message: '📊 Rapport : aucune donnee (le workflow doit etre ACTIF pour collecter).' } }];
const date = new Date().toLocaleDateString('fr-FR', { timeZone: 'Indian/Antananarivo' });
let down = 0;
const lines = names.map(n => {
  const s = t[n];
  const pct = s.checks ? Math.round(100 * s.okChecks / s.checks) : 0;
  if (!s.up) down++;
  return (s.up ? '🟢 ' : '🔴 ') + n + ' : disponibilite ' + pct + ' % (' + s.checks + ' controles)';
});
const head = down === 0 ? '📊 Rapport du ' + date + ' : tout va bien.' : '📊 Rapport du ' + date + ' : ' + down + ' incident(s) a traiter.';
// remise a zero des compteurs pour la journee suivante
names.forEach(n => { t[n].checks = 0; t[n].okChecks = 0; });
return [{ json: { message: head + '\n\n' + lines.join('\n') } }];
